<template>
	<div class="dashboard-page">
		<header class="page-title"><div><span>OPERATIONS OVERVIEW</span><h1>运营首页</h1><p>汇总整条装瓶产线的生产、质量、设备、物流和仓储状态。</p></div><div class="refresh-state"><i></i><span>自动刷新</span><b>2 秒</b></div></header>
		<section class="summary-grid">
			<div><span>累计生产批次</span><strong>{{ dashboard.total }}</strong><small>进入产线</small></div><div><span>完成入库</span><strong>{{ dashboard.completed }}</strong><small>完整流程结束</small></div><div><span>待处理批次</span><strong class="warning">{{ dashboard.holding }}</strong><small>需要人工确认</small></div><div><span>待处理报警</span><strong class="danger">{{ openAlarms.length }}</strong><small>安全与设备异常</small></div><div><span>AGV 任务</span><strong>{{ logistics.tasks.length }}</strong><small>当前调度任务</small></div>
		</section>
		<section class="dashboard-grid">
			<div class="panel production-panel"><div class="panel-title"><div><h2>工序运行状态</h2><p>9 个工位并行连续运行</p></div><el-button type="primary" icon="el-icon-s-operation" @click="$router.push('/factory')">进入控制中心</el-button></div><div class="stage-list"><div v-for="(stage,index) in stages" :key="stage"><span>{{ String(index+1).padStart(2,'0') }}</span><b>{{ stage }}</b><i :class="stageState(index)"></i><small>{{ stageLabel(index) }}</small></div></div></div>
			<div class="panel alarm-panel"><div class="panel-title"><div><h2>最新报警</h2><p>管理端确认后才会关闭</p></div><b class="alarm-count">{{ openAlarms.length }}</b></div><div v-if="!openAlarms.length" class="empty"><i></i>当前无待处理报警</div><div v-for="alarm in openAlarms.slice(0,6)" :key="alarm.alarmId" class="alarm-row"><i></i><div><b>{{ alarmType(alarm.alarmType) }}</b><span>{{ alarm.deviceCode }}</span></div><strong>{{ alarm.value }}</strong></div></div>
		</section>
		<section class="dashboard-grid lower">
			<div class="panel"><div class="panel-title"><div><h2>最近批次</h2><p>最后进入产线的生产记录</p></div></div><div v-for="run in dashboard.runs.slice(0,6)" :key="run.traceCode" class="data-row"><span>{{ run.traceCode }}</span><b>{{ run.bottleType }}</b><small>{{ statusLabel(run.status) }}</small></div></div>
			<div class="panel"><div class="panel-title"><div><h2>物流与仓储</h2><p>AGV 和箱级库存概览</p></div></div><div class="logistics-summary"><div><span>运输任务</span><b>{{ logistics.tasks.length }}</b></div><div><span>仓储箱数</span><b>{{ logistics.stock.length }}</b></div><div><span>仓区数量</span><b>{{ logistics.zones.length }}</b></div><div><span>异常仓区</span><b class="danger">{{ alarmZones }}</b></div></div></div>
		</section>
	</div>
</template>
<script>
import { getFactoryDashboard } from '@/api/FactoryService.js'
import { getOperationsOverview, getLogisticsOverview } from '@/api/OperationsService.js'
export default { data() { return { timer: null, dashboard: { total:0,completed:0,holding:0,runs:[] }, operations: { alarms:[] }, logistics:{tasks:[],zones:[],stock:[]}, stages:['预处理','气体检测','外观检测','饮料准备','灌装','二次检测','机械臂装箱','AGV运输','仓储入库'] } }, computed:{ openAlarms(){ return this.operations.alarms.filter(item=>item.status==='OPEN') }, alarmZones(){ return this.logistics.zones.filter(item=>item.status==='ALARM').length } }, mounted(){ this.load(); this.timer=setInterval(this.load,2000) }, beforeDestroy(){ clearInterval(this.timer) }, methods:{ async load(){ try{ const result=await Promise.all([getFactoryDashboard(),getOperationsOverview(),getLogisticsOverview()]); this.dashboard=result[0]||this.dashboard; this.operations=result[1]||this.operations; this.logistics=result[2]||this.logistics }catch(error){} }, stageState(index){ if(index===1&&this.openAlarms.some(a=>a.alarmType==='VOC_LIMIT'))return'warning'; if(index===7&&this.openAlarms.some(a=>a.alarmType==='AGV_DISTANCE_LIMIT'))return'danger'; return'running' }, stageLabel(index){ const state=this.stageState(index); return state==='running'?'持续运行':state==='warning'?'条件待确认':'异常待处理' }, alarmType(value){return{VOC_LIMIT:'VOC 超限',SMOKE_LIMIT:'烟雾超限',AGV_DISTANCE_LIMIT:'AGV 障碍物'}[value]||value}, statusLabel(value){return{RUNNING:'运行中',COMPLETED:'已入库',REJECTED:'已剔除',HOLD:'待处理'}[value]||value} } }
</script>
